Assumed stack: Node/Express + Redis (`ioredis`). Cache-aside pattern, TTL plus explicit invalidation on writes.

```js
// cache.js
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

const TTL = 300; // seconds
const key = (id) => `user:profile:${id}`;

async function getCached(id, loader) {
  try {
    const hit = await redis.get(key(id));
    if (hit) return JSON.parse(hit);
  } catch (e) {
    console.warn('cache read failed', e.message); // degrade to DB, don't fail request
  }
  const profile = await loader(id);
  if (profile) {
    redis.set(key(id), JSON.stringify(profile), 'EX', TTL).catch(() => {});
  }
  return profile;
}

const invalidate = (id) => redis.del(key(id)).catch(() => {});

module.exports = { getCached, invalidate };
```

```js
// routes/users.js
const { getCached, invalidate } = require('../cache');

router.get('/users/:id/profile', async (req, res) => {
  const profile = await getCached(req.params.id, db.getUserProfile);
  if (!profile) return res.sendStatus(404);
  res.json(profile);
});

router.put('/users/:id/profile', async (req, res) => {
  const updated = await db.updateUserProfile(req.params.id, req.body);
  await invalidate(req.params.id); // after DB write, not before → avoids stale refill race
  res.json(updated);
});
```

Gotchas: cache only the public profile shape. Never cache tokens or password hashes. If the response varies by viewer (privacy settings), include the viewer's role in the key. Redis down → requests fall through to the DB.

